import { z } from 'zod'
import { visibilitySchema } from '@/lib/schemas/visibility'

const MAX_TITLE_LENGTH = 200
const MAX_COLOR_LENGTH = 32
const MAX_LOCATION_LENGTH = 200
const MAX_DESCRIPTION_LENGTH = 2000

export const eventStatusSchema = z.enum(['pending', 'completed'])

const eventBaseShape = z.object({
  title: z.string().min(1, 'Title required').max(MAX_TITLE_LENGTH),
  // Null/omitted = standalone event, not generated by (or linked to) an activity.
  activityId: z.string().uuid().nullable().optional(),
  startAt: z.string().datetime().nullable().optional(),
  endAt: z.string().datetime().nullable().optional(),
  allDay: z.boolean().optional(),
  color: z.string().max(MAX_COLOR_LENGTH).nullable().optional(),
  visibility: visibilitySchema.optional(),
  location: z.string().max(MAX_LOCATION_LENGTH).nullable().optional(),
  description: z.string().max(MAX_DESCRIPTION_LENGTH).nullable().optional(),
})

// An event's end must land strictly after its start. Either side missing
// (null/omitted — an unscheduled or all-day event) skips the check; only a
// PAIR of real instants is cross-validated.
function endAfterStart(d: {
  readonly startAt?: string | null
  readonly endAt?: string | null
}): boolean {
  if (!d.startAt || !d.endAt) return true
  return new Date(d.endAt).getTime() > new Date(d.startAt).getTime()
}

export const createEventSchema = eventBaseShape.refine(endAfterStart, {
  message: 'endAt must be after startAt',
  path: ['endAt'],
})

export type CreateEvent = z.infer<typeof createEventSchema>

// NOTE: no cross-field refine here — a partial update can't see the stored
// counterpart of a one-sided edit (e.g. an endAt-only payload). Cross-field
// enforcement for updates is merge-then-validate in
// `src/server/actions/events.ts`'s `updateEvent` (fetches the current row,
// merges the partial input, re-validates the WHOLE merged object against
// `createEventSchema` before writing) — mirrors the `updateActivity`
// fetch-merge-revalidate precedent.
export const updateEventSchema = eventBaseShape.partial().extend({
  id: z.string().uuid(),
  status: eventStatusSchema.optional(),
  // Manual move/resize gate (mirrors tasks.locked) — UI-only, no server-side
  // startAt/endAt guard by design.
  locked: z.boolean().optional(),
})

export type UpdateEvent = z.infer<typeof updateEventSchema>

export const deleteEventSchema = z.object({
  id: z.string().uuid(),
})

export type DeleteEvent = z.infer<typeof deleteEventSchema>
